mut i := 0 while i < 32 {
let saved := snapshot()
assert_equal(edit(8 + 257 * i, 257), 8 + 257 * i)
assert_equal(has_key(saved, 8 + 257 * i), 0) assert_equal(len(saved), 8 + 257 * i)
i += 1 }
let final := snapshot()
assert_equal(len(final), 8232)
mut k := 0 while k < 8 { assert_equal(final[k], 0) k += 1 }
while k < 8232 { assert_equal(final[k], k) k += 1 }
print("PAIR INSERTION PASS")

